"use client";
/* Holo, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Holo(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("holo"); }, []);
  return React.createElement("piix-holo", piixAttrs(props));
}

export default Holo;
